// UNCHECKED: extends RuntimeException — no forced handling
package com.bank.exception.exception;

import java.math.BigDecimal;

public class InsufficientBalanceException extends RuntimeException {
    private final BigDecimal balance;
    private final BigDecimal requested;

    public InsufficientBalanceException(BigDecimal balance, BigDecimal requested) {
        super("Insufficient balance: Rs." + balance + " for Rs." + requested);
        this.balance = balance;
        this.requested = requested;
    }

    public BigDecimal getBalance() { return balance; }
    public BigDecimal getRequested() { return requested; }
}
// Caller NOT forced to catch. Represents a programming error (should validate first).
