// ─── File: src/main/java/com/bank/exception/controller/TradeController.java ───
package com.bank.exception.controller;

import com.bank.exception.service.TradeProcessingService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/trades")
@RequiredArgsConstructor
public class TradeController {

    private final TradeProcessingService service;

    @PostMapping("/validate")
    public String validate(@RequestParam String symbol, @RequestParam BigDecimal amount) {
        service.validateTrade(symbol, amount);
        // If validation fails → TradeValidationException (unchecked)
        // → GlobalExceptionHandler catches → returns 422 with ErrorResponse
        // Controller doesn't need try-catch! Clean!
        return "Trade valid: " + symbol + " Rs." + amount;
    }

    @PostMapping("/withdraw")
    public String withdraw(@RequestParam BigDecimal balance, @RequestParam BigDecimal amount) {
        service.withdraw(balance, amount);
        // InsufficientBalanceException (unchecked) → GlobalExceptionHandler → 400
        return "Withdrawn Rs." + amount;
    }
}
