```java
// ─── File: src/test/java/com/bank/exception/CheckedVsUncheckedTest.java ───
package com.bank.exception;

import com.bank.exception.exception.*;
import com.bank.exception.service.TradeProcessingService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class CheckedVsUncheckedTest {

    TradeProcessingService service = new TradeProcessingService();

    // ═══ CHECKED: compiler forces handling ═══
    @Test
    void checked_mustCatchOrDeclareThrows() {
        // service.readTradeFile("/nonexistent");
        // ↑ Without try-catch or throws: COMPILE ERROR!
        // "Unhandled exception: TradeFileNotFoundException"

        assertThatThrownBy(() -> service.readTradeFile("/nonexistent/file.csv"))
            .isInstanceOf(TradeFileNotFoundException.class)
            .hasMessageContaining("not found");
    }

    @Test
    void checked_extendsException() {
        assertThat(Exception.class.isAssignableFrom(TradeFileNotFoundException.class)).isTrue();
        assertThat(RuntimeException.class.isAssignableFrom(TradeFileNotFoundException.class)).isFalse();
        // Checked: extends Exception but NOT RuntimeException
    }

    // ═══ UNCHECKED: no forced handling ═══
    @Test
    void unchecked_noCompilerForcing() {
        // This compiles WITHOUT try-catch or throws:
        assertThatThrownBy(() -> service.withdraw(new BigDecimal("1000"), new BigDecimal("5000")))
            .isInstanceOf(InsufficientBalanceException.class)
            .hasMessageContaining("Insufficient");
        // InsufficientBalanceException extends RuntimeException → unchecked
    }

    @Test
    void unchecked_extendsRuntimeException() {
        assertThat(RuntimeException.class.isAssignableFrom(InsufficientBalanceException.class)).isTrue();
        assertThat(RuntimeException.class.isAssignableFrom(TradeValidationException.class)).isTrue();
    }

    // ═══ CHECKED with recovery ═══
    @Test
    void checked_recoveryWithFallback() {
        // Both files missing → RuntimeException (gave up recovering)
        assertThatThrownBy(() -> service.readTradeFileWithFallback("/primary", "/backup"))
            .isInstanceOf(RuntimeException.class)
            .hasMessageContaining("Both");
        // readTradeFileWithFallback CATCHES checked exception and tries backup — recovery!
    }

    // ═══ UNCHECKED business validation ═══
    @Test
    void unchecked_validationException() {
        assertThatThrownBy(() -> service.validateTrade("", new BigDecimal("100")))
            .isInstanceOf(TradeValidationException.class)
            .hasMessageContaining("required");

        assertThatThrownBy(() -> service.validateTrade("RELIANCE", new BigDecimal("-1")))
            .isInstanceOf(TradeValidationException.class)
            .hasMessageContaining("positive");
    }

    // ═══ HIERARCHY ═══
    @Test
    void exceptionHierarchy() {
        // Throwable
        //   ├── Error (unchecked — don't catch: OOM, StackOverflow)
        //   └── Exception (CHECKED)
        //         ├── IOException, SQLException (checked)
        //         └── RuntimeException (UNCHECKED)
        //               ├── NullPointerException
        //               ├── IllegalArgumentException
        //               └── our custom: InsufficientBalanceException, TradeValidationException

        assertThat(Throwable.class.isAssignableFrom(Exception.class)).isTrue();
        assertThat(Exception.class.isAssignableFrom(RuntimeException.class)).isTrue();
    }
}
